{
  "regions": [
    {
      "id": "r2",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "रूपतिरस्कारमाह ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "स्तनौ मांसग्रन्थी कनककलशावित्युपमितौ",
          "end": "line"
        },
        {
          "n": 2,
          "text": "मुखं श्लेष्मागारं तदपि च शशाङ्केन तुलितम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "स्रवन्मूत्रक्लिन्नं करिवरकरस्पर्धि जघन-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "महो निन्द्यं रूपं कविजनविशेषैर्गुरु कृतम् ॥ २० ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "अजानन्माहात्म्यं पततु शलभो दीपदहने",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स मीनोप्यज्ञानाद्वडिशयुतमश्नातु पिशितम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "विजानन्तोप्येते वयमिह विपज्जालजटिला-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "न्न मुञ्चामः कामानहह गहनो मोहमहिमा ॥ २१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथ दुर्जनमुद्दिश्याह ।",
          "end": "space"
        },
        {
          "n": 2,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "बिसमलमशनाय स्वादु पानाय तोयं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "शयनमवनिपृष्ठे वल्कले वाससी च ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "",
          "end": "line"
        },
        {
          "n": 4,
          "text": "नवधनमधुपानभ्रान्तसर्वेन्द्रियाणा-",
          "end": "hyphen"
        },
        {
          "n": 5,
          "text": "मविनयमनुमन्तुं नोत्सहे दुर्जनानाम् ॥ २२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "XX. (c) कर; शिरः T. N. कट M. (d) °नमहो नि°; °नं मुहुर्नि° B. T.",
          "end": "space"
        },
        {
          "n": 2,
          "text": "K. Bo. N. R. G. P. जन; वर. K. Bo. (orig. Bo.n.) M.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "XXI. (a) °न्माहात्म्यम्; °न्नप्येषः A. °न्दाहात्म्यम् P. R. N. पततु; पत-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "ति. B. K. Bo. विशति. T. °भो दीप; °भस्तीव्र. A. B. T. K. N. R. P. G.",
          "end": "space"
        },
        {
          "n": 3,
          "text": "Bo. M. (b) °प्य; °पि. M. °ज्ञानाद्व°; °ज्ञानाद्बि° R. P. B. °ज्ञात्वाब. T.",
          "end": "space"
        },
        {
          "n": 4,
          "text": "°श्नातु; °श्नन्ति. Bo. °श्नाति. T. K. G. Bo.n. (c) °प्ये°; °ह्ये°. K. Bo.",
          "end": "space"
        },
        {
          "n": 5,
          "text": "(orig. Bo.n.) G. जटि°; पट°. K. Bo. (orig. Bo.n.) G.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "XXII. (a). बिस; फल. A. B. T. K. Bo. R. P. (b) °ष्ठे; °ष्ठम. P. R.",
          "end": "space"
        },
        {
          "n": 2,
          "text": "शयनमवनिपृष्ठे; क्षितिरपि शयनार्थम्. N. वल्कले वाससी; वाससी वल्कले. A. T. K.",
          "end": "space"
        },
        {
          "n": 3,
          "text": "",
          "end": "space"
        },
        {
          "n": 4,
          "text": "Bo. वाससी वल्कलम्. N. च; तु. P. नु. R. (c) नवधन; न धवल. A. धनलव. B.",
          "end": "space"
        },
        {
          "n": 5,
          "text": "T. K. Bo. °नभ्रान्त; °नं भ्रान्त. A. M. °नभ्रामि. K. (d) °मनुमन्तुम्;",
          "end": "space"
        },
        {
          "n": 6,
          "text": "°मनुवर्तुम्. T. मुपगन्तुम् A. नो°; को°. A.",
          "end": "space"
        }
      ],
